def transform(grid):
    """Fill each single-cell horizontal gap between matching foreground cells with 2."""
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == row[c + 1] != background:
                out[r][c] = 2
    return out
